<?php
require __DIR__.'/../src/bootstrap.php';$user=requireLogin();$id=intField($_GET,'id')??0;$db=Database::connection();$q=$db->prepare('SELECT o.*,p.code point_code,p.name point_name,w.code warehouse_code,w.name warehouse_name FROM sales_orders o JOIN sales_points p ON p.id=o.sales_point_id JOIN warehouses w ON w.id=o.warehouse_id WHERE o.id=:id');$q->execute(['id'=>$id]);$order=$q->fetch();if(!$order)forbid('ORDER_NOT_FOUND');if(!canAccessWarehouse($user,(int)$order['warehouse_id'])&&!canAccessSalesPoint($user,(int)$order['sales_point_id']))forbid('ORDER_SCOPE_FORBIDDEN');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requirePost();try{$action=field($_POST,'action');if($action==='approve')SalesOrderService::approve($user,$id);elseif($action==='dispatch'){ $lines=[];$q2=$db->prepare('SELECT * FROM sales_order_lines WHERE order_id=:id');$q2->execute(['id'=>$id]);foreach($q2 as $l){$remaining=(int)$l['requested_qty']-(int)$l['allocated_qty'];if($remaining>0)$lines[]=['batch_id'=>$l['batch_id'],'qty'=>$remaining];}SalesOrderService::dispatch($user,$id,$lines,field($_POST,'request_key'));}elseif($action==='receive'){ $received=[];$batchIds=listField($_POST,'batch_id');$qtys=listField($_POST,'received_qty');foreach($batchIds as $i=>$b)$received[(int)$b]=$qtys[$i]??null;SalesOrderService::receive($user,(int)$_POST['delivery_id'],$received);}flash('Đã cập nhật đơn phân phối.');redirect('/sales-order.php?id='.$id);}catch(DomainException $e){$error=ERROR_LABELS[$e->getMessage()]??'Không cập nhật được đơn phân phối. Trạng thái đơn có thể đã thay đổi; tải lại trang rồi thử lại.';}catch(Throwable $e){error_log('Sales order update failed: '.$e->getMessage());$error='Không cập nhật được đơn phân phối. Vui lòng thử lại.';}}
$lq=$db->prepare('SELECT l.*,i.name item_name,b.code batch_code FROM sales_order_lines l JOIN items i ON i.id=l.item_id JOIN batches b ON b.id=l.batch_id WHERE l.order_id=:id ORDER BY l.id');$lq->execute(['id'=>$id]);$lines=$lq->fetchAll();$dq=$db->prepare('SELECT * FROM sales_deliveries WHERE order_id=:id ORDER BY id');$dq->execute(['id'=>$id]);$deliveries=$dq->fetchAll();$dlq=$db->prepare('SELECT dl.*,i.name item_name,b.code batch_code FROM sales_delivery_lines dl JOIN sales_order_lines ol ON ol.id=dl.order_line_id JOIN items i ON i.id=ol.item_id JOIN batches b ON b.id=dl.batch_id WHERE dl.delivery_id=:id ORDER BY dl.id');foreach($deliveries as &$delivery){$dlq->execute(['id'=>$delivery['id']]);$delivery['lines']=$dlq->fetchAll();}unset($delivery);$title=$order['code'];$active='sales-orders';require __DIR__.'/../templates/header.php';
?>
<nav class="breadcrumb"><a href="/sales-orders.php">Đơn phân phối</a> / <?=e($order['code'])?></nav><header class="page-head"><div><h1><?=e($order['code'])?></h1><p><?=e($order['warehouse_name'].' → '.$order['point_name'])?> · <strong><?=e($order['status'])?></strong></p></div></header>
<?php if($error):?><div class="error-summary" role="alert"><?=e($error)?></div><?php endif;?>
<section class="card"><table class="table"><thead><tr><th>Mặt hàng</th><th>Lô</th><th class="num">Đặt</th><th class="num">Đã phân bổ</th></tr></thead><tbody><?php foreach($lines as $l):?><tr><td><?=e($l['item_name'])?></td><td><?=e($l['batch_code'])?></td><td class="num"><?=e($l['requested_qty'])?></td><td class="num"><?=e($l['allocated_qty'])?></td></tr><?php endforeach;?></tbody></table><div class="actions"><?php if(in_array($order['status'],['PENDING'],true)&&in_array($user['role'],['approver','admin','central_manager','regional_manager'],true)):?><form method="post"><?=csrfInput()?><input type="hidden" name="action" value="approve"><button class="button">Duyệt đơn</button></form><?php endif;?><?php if(in_array($order['status'],['APPROVED','DELIVERING','PARTIALLY_RECEIVED'],true)&&in_array($user['role'],['staff','regional_manager','admin'],true)&&array_sum(array_map(fn($l)=>(int)$l['requested_qty']-(int)$l['allocated_qty'],$lines))>0):?><form method="post"><?=csrfInput()?><input type="hidden" name="action" value="dispatch"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><button class="button">Xuất phần còn lại</button></form><?php endif;?></div></section>
<?php foreach($deliveries as $d):?><section class="card"><h2>Giao hàng #<?=$d['id']?> · <?=e($d['status'])?></h2><?php if(in_array($d['status'],['DELIVERING','PARTIALLY_RECEIVED'],true)&&canAccessSalesPoint($user,(int)$order['sales_point_id'])):?><form method="post"><?=csrfInput()?><input type="hidden" name="action" value="receive"><input type="hidden" name="delivery_id" value="<?=$d['id']?>"><?php foreach($d['lines'] as $dl):?><input type="hidden" name="batch_id[]" value="<?=$dl['batch_id']?>"><label class="form-field"><?=e($dl['item_name'].' · '.$dl['batch_code'].' (giao '.$dl['shipped_qty'].')')?><input type="number" min="<?=e((string)($dl['received_qty']??0))?>" max="<?=e($dl['shipped_qty'])?>" name="received_qty[]" value="<?=e((string)($dl['received_qty']??0))?>" required></label><?php endforeach;?><button class="button">Xác nhận số nhận</button></form><?php else:foreach($d['lines'] as $dl):?><p><?=e($dl['item_name'].' · '.$dl['batch_code'])?> · Đã giao: <?=e($dl['shipped_qty'])?> · Thực nhận: <?=e((string)$dl['received_qty'])?> · Thiếu: <?=e($dl['shortage_qty'])?></p><?php endforeach;endif;?></section><?php endforeach;?>
